// Why Code: one UNION over the queues in settings, each with its own rows query; the list comes from build.py.
const s = $('Page settings').first().json;
const want = ($('Review page').first().json.query.q || '').toLowerCase();
const qs = s.queues.filter(q => !want || q.key.startsWith(want) || q.label.toLowerCase().startsWith(want));
const parts = qs.map(q => `(select '${q.key}'::text as queue, to_jsonb(x) as r from (${q.rows}) x order by x.since nulls last limit ${Number(s.per_queue) || 100})`);
return [{ json: { sql: parts.length ? parts.join(' union all ') : 'select null::text as queue, null::jsonb as r where false', keys: qs.map(q => q.key) } }];

// Why Code: an HTML page with a section per queue; the HTML node can't loop over groups.
const s = $('Page settings').first().json;
const q = $('Review page').first().json.query;
const byKey = Object.fromEntries(s.queues.map(x => [x.key, x]));
const rows = $input.all().map(i => i.json).filter(r => r.queue && r.r);
const esc = t => String(t ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const groups = {};
for (const r of rows) (groups[r.queue] = groups[r.queue] || []).push(r.r);
const order = s.queues.map(x => x.key).filter(k => groups[k]);
const sections = order.map(k => {
  const qd = byKey[k];
  const items = groups[k].map(r => `<label class="item"><input type="checkbox" data-q="${esc(k)}" value="${esc(r.id)}"><span><b>${esc(r.label)}</b><small>${esc(r.detail)}</small></span><em class="st" id="st-${esc(k)}-${esc(r.id)}"></em></label>`).join('');
  const btns = `<button data-q="${esc(k)}" data-d="approve" class="go">${esc(qd.replay?.approve_label || 'Approve')} ticked</button>` + (qd.replay?.reject ? `<button data-q="${esc(k)}" data-d="reject">${esc(qd.replay?.reject_label || 'Reject')} ticked</button>` : '');
  return `<section><h2>${esc(qd.label)} <span>${groups[k].length}</span></h2><p class="bar"><label><input type="checkbox" class="all" data-q="${esc(k)}"> Tick all</label>${btns}</p>${items}</section>`;
}).join('') || '<p class="none">Nothing waiting for a decision.</p>';
const auth = JSON.stringify({ u: q.u, n: q.n, exp: q.exp, q: q.q || '', sig: q.sig });
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(s.store_name)} · Review</title><style>
:root{--ink:#1d1c1d;--muted:#616061;--line:#e8e8e8;--go:#007a5a;--bg:#fff}
*{box-sizing:border-box}body{margin:0;font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif;color:var(--ink);background:var(--bg)}
main{max-width:860px;margin:0 auto;padding:16px}h1{font-size:20px;margin:8px 0 16px}h2{font-size:16px;margin:28px 0 8px;display:flex;gap:8px;align-items:center}h2 span{font-size:12px;background:#f0f0f0;border-radius:10px;padding:1px 8px}
.bar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:0 0 8px}.bar label{margin-right:auto;color:var(--muted)}
button{font:inherit;border:1px solid #bbb;background:#fff;border-radius:6px;padding:6px 12px;cursor:pointer}button.go{background:var(--go);border-color:var(--go);color:#fff}button:disabled{opacity:.5}
.item{display:flex;gap:10px;align-items:flex-start;padding:10px 4px;border-top:1px solid var(--line)}.item span{flex:1;min-width:0}.item b{display:block;font-weight:600}.item small{display:block;color:var(--muted);overflow-wrap:anywhere}
.st{font-style:normal;font-size:13px;white-space:nowrap}.ok{color:var(--go)}.err{color:#b3261e}.none{color:var(--muted)}
</style></head><body><main><h1>${esc(s.store_name)}: waiting for a decision</h1><p class="none">Each decision goes through its workflow exactly as a button tap in Slack would, and the card updates there too.</p>${sections}</main><script>
const AUTH=${auth};const URL_=${JSON.stringify(s.decide_url)};
document.querySelectorAll('.all').forEach(a=>a.onchange=()=>document.querySelectorAll('input[data-q="'+a.dataset.q+'"]:not(.all)').forEach(c=>{if(!c.disabled)c.checked=a.checked}));
document.querySelectorAll('button[data-d]').forEach(b=>b.onclick=async()=>{
 const boxes=[...document.querySelectorAll('input[data-q="'+b.dataset.q+'"]:not(.all):checked')];if(!boxes.length)return;
 const btns=document.querySelectorAll('button');btns.forEach(x=>x.disabled=true);
 for(let i=0;i<boxes.length;i+=10){const chunk=boxes.slice(i,i+10);chunk.forEach(c=>document.getElementById('st-'+b.dataset.q+'-'+c.value).textContent='working…');
  try{const r=await fetch(URL_,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({...AUTH,decisions:chunk.map(c=>({queue:b.dataset.q,id:c.value,decision:b.dataset.d}))})});const j=await r.json();
   for(const x of (j.results||[])){const el=document.getElementById('st-'+x.queue+'-'+x.id);if(el){el.textContent=x.message;el.className='st '+(x.ok?'ok':'err')}const cb=document.querySelector('input[data-q="'+x.queue+'"][value="'+x.id+'"]');if(cb&&x.ok){cb.checked=false;cb.disabled=true}}
   if(j.message&&!j.results)chunk.forEach(c=>{const el=document.getElementById('st-'+b.dataset.q+'-'+c.value);el.textContent=j.message;el.className='st err'});
  }catch(e){chunk.forEach(c=>{const el=document.getElementById('st-'+b.dataset.q+'-'+c.value);el.textContent='No answer, try again';el.className='st err'})}}
 btns.forEach(x=>x.disabled=false);});
</script></body></html>`;
return [{ json: { html } }];

// Why Code: the lookup is a UNION over only the queues these decisions touch, each with its own rows query.
const s = $('Decide settings').first().json;
const d = ($('Page decision').first().json.body.decisions || []).slice(0, 10);
const keys = [...new Set(d.map(x => x.queue))].filter(k => s.queues.some(q => q.key === k));
const parts = keys.map(k => `(select '${k}'::text as queue, to_jsonb(x) as r from (${s.queues.find(q => q.key === k).rows}) x where '${k}:' || x.id = any($1::text[]))`);
return [{ json: { sql: parts.length ? parts.join(' union all ') : 'select null::text as queue, null::jsonb as r where $1::text[] is null', ids: d.map(x => `${x.queue}:${x.id}`) } }];

// Why Code: picks each queue's button (a row can override it) and where its card is; per queue, from settings.
const s = $('Decide settings').first().json;
const found = Object.fromEntries($input.all().filter(i => i.json.queue).map(i => [`${i.json.queue}:${i.json.r.id}`, i.json.r]));
const out = [];
for (const x of ($('Page decision').first().json.body.decisions || []).slice(0, 10)) {
  const q = s.queues.find(z => z.key === x.queue);
  const r = found[`${x.queue}:${x.id}`];
  const base = { queue: x.queue, id: x.id, decision: x.decision };
  if (!q || !r) { out.push({ json: { ...base, skip: 'Already decided' } }); continue; }
  const action = x.decision === 'approve' ? (r.approve_action || q.replay.approve) : (r.reject_action || q.replay.reject);
  if (!action) { out.push({ json: { ...base, skip: 'No such button on this card' } }); continue; }
  const channel = r.channel || q.channel;
  out.push({ json: { ...base, label: r.label, action, value: r.value, channel, ts: r.ts || '', path: q.replay.path,
    history: r.ts ? `channel=${encodeURIComponent(channel)}&latest=${r.ts}&inclusive=true&limit=1` : `channel=${encodeURIComponent(channel)}&limit=200` } });
}
return out;

// Why Code: builds Slack's block_actions payload, including state from the card's own inputs, and the signing base string.
const s = $('Decide settings').first().json;
const who = $('Page decision').first().json.body;
const plans = $('Plan the taps').all().map(i => i.json);
const stateOf = blocks => { const v = {}; for (const b of blocks || []) { const els = b.type === 'input' ? [b.element] : b.type === 'actions' ? b.elements : b.accessory ? [b.accessory] : []; for (const e of els) { if (!e || !e.action_id) continue; let val;
  if (e.type === 'checkboxes' || e.type === 'multi_static_select') val = { type: e.type, selected_options: e.initial_options || [] };
  else if (e.type === 'radio_buttons' || e.type === 'static_select') val = { type: e.type, selected_option: e.initial_option || null };
  else if (e.type === 'plain_text_input') val = { type: e.type, value: e.initial_value ?? null };
  else continue; (v[b.block_id] = v[b.block_id] || {})[e.action_id] = val; } } return v; };
const findButton = (blocks, action, value) => { for (const b of blocks || []) for (const e of (b.elements || []).concat(b.accessory ? [b.accessory] : [])) if (e.action_id === action && (value == null || e.value === value)) return { block_id: b.block_id, e }; return null; };
return $input.all().map((it, i) => {
  const p = plans[i];
  if (p.skip) return { json: p };
  const msgs = it.json?.messages || [];
  const msg = p.ts ? msgs.find(m => m.ts === p.ts) || msgs[0] : msgs.find(m => findButton(m.blocks, p.action, p.value));
  const ts = p.ts || msg?.ts;
  if (!ts) return { json: { ...p, skip: 'Card not found in Slack' } };
  const btn = findButton(msg?.blocks, p.action, p.value) || findButton(msg?.blocks, p.action, null);
  const now = Math.floor(Date.now() / 1000);
  const payload = { type: 'block_actions', api_app_id: s.slack_app_id || '', team: { id: s.slack_team_id || '' },
    user: { id: who.u, username: who.n, name: who.n }, channel: { id: p.channel }, container: { type: 'message', message_ts: ts, channel_id: p.channel },
    message: { ts, text: msg?.text || '', blocks: msg?.blocks || [] }, state: { values: stateOf(msg?.blocks) },
    actions: [{ type: 'button', action_id: p.action, value: btn?.e?.value ?? p.value, block_id: btn?.block_id || '', action_ts: String(now) }],
    response_url: '', trigger_id: '' };
  const body = 'payload=' + encodeURIComponent(JSON.stringify(payload));
  return { json: { ...p, ts, body, now: String(now), base: `v0:${now}:${body}`, url: s.internal_url.replace(/\/$/, '') + '/webhook/' + p.path } };
});

// Why Code: matches each decision to whether its row left the queue, for the page's per-item status.
const still = new Set($input.all().filter(i => i.json.queue).map(i => `${i.json.queue}:${i.json.r.id}`));
const done = { approve: 'Approved', reject: 'Rejected' };
const results = $('Build the taps').all().map(i => i.json).map(p => {
  if (p.skip) return { queue: p.queue, id: p.id, ok: p.skip === 'Already decided', message: p.skip };
  const left = !still.has(`${p.queue}:${p.id}`);
  return { queue: p.queue, id: p.id, ok: left, message: left ? (done[p.decision] || 'Done') : 'Still waiting: open the card in Slack to see why' };
});
return [{ json: { results, log: results.map(r => `${r.queue}:${r.id} ${r.message}`).join('; ') } }];
